css:
.lc { display: grid; gap: clamp(1.6rem, 4vw, 3rem); margin: 0; }
@media (min-width: 62rem) { .lc { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.lc__card { border-top: 1px solid var(--bff-line, rgba(21,38,26,.22)); padding-top: 1.2rem; }
.lc__t { margin: 0 0 .25em; font-size: clamp(1.45rem, 1.1rem + 1.2vw, 2rem); line-height: 1.15; letter-spacing: -.015em; }
.lc__p { margin: 0 0 1rem; color: var(--os-color-text-muted); max-width: 62ch; }
.lc__card a { text-decoration: none; display: inline-flex; }
.lc__btn { display: inline-flex; align-items: center; justify-content: center; padding: .6em 1.1em; border: 2px solid currentColor; border-radius: 999px; font: 700 .95rem/1.1 var(--os-font-body); color: var(--os-color-heading); transition: background-color .2s; }
.lc__btn:hover { background: var(--os-color-heading); color: var(--os-color-background); }
@media (max-width: 767px) { .lc__btn { min-height: 2.75rem; } }
@media (prefers-reduced-motion: reduce) { .lc__btn { transition: none; } }
